use crate::error::{ConfigError, PriorityError};

/// Identifier generated by one controller instance.
#[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]
pub struct RequestId(u64);

impl RequestId {
    pub const fn value(self) -> u64 {
        self.0
    }

    pub(crate) const fn new(value: u64) -> Self {
        Self(value)
    }
}

/// Monotonic timestamp expressed in milliseconds.
#[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]
pub struct Timestamp(u64);

impl Timestamp {
    pub const fn from_millis(value: u64) -> Self {
        Self(value)
    }

    pub const fn as_millis(self) -> u64 {
        self.0
    }
}

impl From<u64> for Timestamp {
    fn from(value: u64) -> Self {
        Self::from_millis(value)
    }
}

/// Request priority in the inclusive range `0..=767`; lower values are more important.
#[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]
pub struct Priority(u16);

impl Priority {
    pub const HIGHEST: u16 = 0;
    pub const LOWEST: u16 = 767;
    pub const ALLOW_ALL_THRESHOLD: u16 = 768;
    pub const TIERS: u8 = 6;
    pub const COHORTS_PER_TIER: u8 = 128;

    pub fn new(value: u16) -> Result<Self, PriorityError> {
        if value > Self::LOWEST {
            return Err(PriorityError::ValueOutOfRange { value });
        }
        Ok(Self(value))
    }

    pub fn from_tier(tier: u8, cohort: u8) -> Result<Self, PriorityError> {
        if tier >= Self::TIERS {
            return Err(PriorityError::TierOutOfRange { tier });
        }
        if cohort >= Self::COHORTS_PER_TIER {
            return Err(PriorityError::CohortOutOfRange { cohort });
        }
        Self::new(u16::from(tier) * u16::from(Self::COHORTS_PER_TIER) + u16::from(cohort))
    }

    pub const fn value(self) -> u16 {
        self.0
    }
}

/// Initial fixed limits for a controller instance.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct Config {
    pub initial_threshold: u16,
    pub max_concurrent_requests: usize,
    pub max_queued_requests: usize,
    pub queue_timeout_ms: u64,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            initial_threshold: Priority::ALLOW_ALL_THRESHOLD,
            max_concurrent_requests: 10,
            max_queued_requests: 1_000,
            queue_timeout_ms: 500,
        }
    }
}

impl Config {
    pub(crate) fn validate(self) -> Result<Self, ConfigError> {
        if self.initial_threshold > Priority::ALLOW_ALL_THRESHOLD {
            return Err(ConfigError::ThresholdOutOfRange {
                value: self.initial_threshold,
            });
        }
        if self.max_concurrent_requests == 0 {
            return Err(ConfigError::ZeroConcurrency);
        }
        if self.queue_timeout_ms == 0 {
            return Err(ConfigError::ZeroQueueTimeout);
        }
        Ok(self)
    }
}

/// Host-reported result of started work.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum Outcome {
    Success,
    Failure,
}

/// Reason why submitted work was not admitted.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum RejectionReason {
    Threshold { priority: Priority, threshold: u16 },
    QueueFull,
    Shutdown,
}

/// Reason why queued work expired.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum EvictionReason {
    QueueTimeout,
}

/// Reason why queued work was cancelled.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum CancellationReason {
    Requested,
    Shutdown,
}

/// Decision that the embedding host must apply.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum Action {
    Start {
        request_id: RequestId,
    },
    Reject {
        request_id: RequestId,
        reason: RejectionReason,
    },
    Evict {
        request_id: RequestId,
        reason: EvictionReason,
    },
    Cancel {
        request_id: RequestId,
        reason: CancellationReason,
    },
}

/// Result of submitting one request to the controller.
#[derive(Clone, Debug, Eq, PartialEq)]
#[must_use]
pub struct Submission {
    pub request_id: RequestId,
    pub actions: Vec<Action>,
}
